// @ts-nocheck – scaffold generated by scripts/build-manifest.mjs; props mirror the manifest's Figma properties.
// Fill FIGMA_NODE_URL once the kit exists, then run `pnpm figma:connect` to publish.
import figma from '@figma/code-connect';
import { DisplayNumber } from '@davinci-ai/react';

const FIGMA_NODE_URL = 'FIGMA_NODE_URL'; // e.g. https://www.figma.com/design/<file>?node-id=<id>  (Foundations/DisplayNumber)

figma.connect(DisplayNumber, FIGMA_NODE_URL, {
  props: {
    unit: figma.string('unit'),
    size: figma.enum('size', { '42': 42, '48': 48, '64': 64 }),
  },
  example: ({ unit, size }) => (
    <DisplayNumber unit={unit} size={size}></DisplayNumber>
  ),
});
